# Conflict-Driven Clause-Learning SAT Solver (1UIP) in Plain Node.js

**Environment:** Node 20+ (tested on v22) · **Dependencies:** none · **I/O:** DIMACS CNF on stdin

## Root-Cause Analysis

A complete SAT solver for arbitrary CNF formulas cannot be a greedy or tree-enumerating (DPLL-only) searcher and still meet the runtime target. The failure modes of a partial/naive solution — and the design decisions that eliminate each one — are:

| Naive approach | Why it fails | Fix used here |
|---|---|---|
| DPLL with chronological backtracking | Repeats the same dead-end subproblems; exponential blow-up even on easy random 3-CNF; PHP(n,n-1) is intractable | Conflict analysis learns an **asserting 1UIP clause** per conflict and **backjumps non-chronologically** to the asserting decision level, so every conflict permanently prunes a decision-level frontier |
| BCP by clause re-scanning | O(clauses) per assignment; no knowledge of what became false | **Two-watched-literals** with a propagation queue: each clause is only inspected when *one of its two watched literals becomes false*, and unit/conflict detection is amortized |
| Deciding literals in static order | Poor for structured+random mixtures; restarts useless | **VSIDS** (activity counters, exponential recency decay `inc *= 1/0.95`, periodic rescaling when activities exceed `1e20`) with **phase saving** (decide into the last-known value) and **Luby restarts** |
| Dropping watch repair after a backjump | Costly re-propagation, or worse, missed unit/conflict detections | The watch invariant *"no clause ever has two false watches"* is maintained lazily — backjumping only *removes* assignments, which can never create a new false literal — so **no re-propagation is needed beyond the asserting literal** of each learned clause |
| Trusting a final assignment | Can emit an invalid model or both a literal and its negation | Every candidate model is **re-checked clause-by-clause** (including learned clauses) before printing; the model line contains exactly one literal per variable, so a literal and its negation can never coexist |

Termination is guaranteed even with restarts: every conflict adds a new distinct learned clause, and the 1UIP clause is asserting at its backjump level, so the clause database strictly grows (finite).

> Implementation pitfall actually hit during development: a xorshift32 PRNG written with JS `<<` semantics can yield *negative* values / `-0`, turning generated literals into `0` and silently corrupting test instances. The generator forces unsigned 32-bit output (`s >>> 0`).

## Exact Fix

### File `sat.js` (the solver — complete source)

```javascript
#!/usr/bin/env node
/*
 * CDCL SAT solver with 1UIP clause learning — plain Node.js, zero dependencies.
 *
 * Usage:
 *   node sat.js < formula.cnf            # DIMACS CNF on stdin
 *   node sat.js --selftest               # battery of self-tests (UNSAT/SAT polarities)
 *
 * Output for a formula:
 *   UNSAT                                    (unsatisfiable)
 *   SAT
 *   1 -2 3 ... n                             (one non-zero literal per variable,
 *                                             model verified before printing)
 *
 * Implementation notes:
 *  - Two-watched-literal boolean constraint propagation with a propagation
 *    queue; watch lists are never repaired on backtrack/backjump — the watch
 *    invariant ("no clause ever has two false watches") is preserved because
 *    backtracking only *removes* assignments, so no re-propagation is required
 *    beyond the asserting literal of each learned clause.
 *  - Activity-based VSIDS decision heuristic with exponential recency decay and
 *    periodic rescaling; phase saving records the last value of every variable.
 *  - First-UIP conflict analysis producing an asserting learned clause and
 *    non-chronological backjumping to the asserting decision level.
 *  - Luby-style restarts with phase saving (deterministic, no randomization).
 *  - Every candidate model is re-checked clause-by-clause before printing; a
 *    model is emitted as exactly one literal per variable, so a literal and its
 *    negation can never both appear.
 */
'use strict';

const fs = require('fs');

const abs = Math.abs;

// ---------------------------------------------------------------------------
// Deterministic RNG (xorshift32) — keeps self-tests reproducible
// ---------------------------------------------------------------------------
function makeRng(seed) {
  let s = seed & 0xffffffff;
  if (s === 0) s = 0x9e3779b9;
  return function next() {
    s ^= s << 13; s &= 0xffffffff;
    s ^= s >> 17;
    s ^= s << 5; s &= 0xffffffff;
    return s >>> 0;                            // force unsigned 32-bit output
  };
}

// Luby restart sequence, μ(1..): 1,1,2,1,1,2,4,1,1,2,1,1,2,4,8,...
function luby(i) {
  let k = 1;
  while ((1 << k) - 1 < i) k++;
  if (i === (1 << k) - 1) return 1 << (k - 1);
  return luby(i - (1 << (k - 1)) + 1);
}

// Remove duplicate variables from a clause; returns null for tautologies.
// (Tautological clauses are always satisfied and can be dropped.)
function sanitize(clause) {
  const map = new Map(); // var -> stored literal
  let tautology = false;
  for (const l of clause) {
    if (l === 0) continue;
    const v = abs(l);
    if (map.has(v)) {
      if (map.get(v) !== l) { tautology = true; break; }
    } else {
      map.set(v, l);
    }
  }
  if (tautology) return null;
  return [...map.values()];
}

// ---------------------------------------------------------------------------
// CDCL solver core
// ---------------------------------------------------------------------------
class CDCL {
  // clauses: array of arrays of non-zero literals (1..n positive, -1..-n negative)
  constructor(n, clauses) {
    this.n = n;
    this.clauses = clauses;                    // clause DB (grows with learned clauses)
    this.val = new Int32Array(n + 1);          // 0 unassigned, +1 true, -1 false
    this.lvl = new Int32Array(n + 1);          // decision level of assignment
    this.reason = new Int32Array(n + 1).fill(-1); // clause index, -1 = decision
    this.phase = new Int32Array(n + 1);        // phase saving (last value per var)
    this.act = new Float64Array(n + 1).fill(1.0); // VSIDS activity
    this.trail = [];                           // assigned literals in trail order
    this.fq = [];                              // propagation queue (falsified literals)
    this.fqPtr = 0;
    this.decisionLevel = 0;
    this.inc = 1.0;                            // VSIDS exponential recency increment
    this.conflicts = 0;
    this.conflictsSinceRestart = 0;
    this.restarts = 0;
    // two-watched-literal data
    this.w1 = new Array(clauses.length).fill(0);
    this.w2 = new Array(clauses.length).fill(0);
    this.watches = Array.from({ length: 2 * n + 1 }, () => []);
  }

  li(l) { return l > 0 ? l : this.n - l; }      // literal -> watch bucket in 1..2n
  litVal(l) { const v = abs(l); const a = this.val[v]; return l > 0 ? a : -a; }

  assignLit(lit, dl, why) {
    const v = abs(lit);
    if (this.val[v] !== 0) throw new Error('internal: double assignment of var ' + v);
    this.val[v] = lit > 0 ? 1 : -1;
    this.lvl[v] = dl;
    this.reason[v] = why;
    this.phase[v] = this.val[v];               // phase saving snapshot
    this.trail.push(lit);
    this.fq.push(-lit);                        // -lit is the literal that just became false
  }

  // Boolean constraint propagation (two-watched literals). Returns -1 if no
  // conflict, otherwise the index of the falsified (conflicting) clause.
  propagate() {
    const W = this.watches, w1 = this.w1, w2 = this.w2, cls = this.clauses;
    while (this.fqPtr < this.fq.length) {
      const fl = this.fq[this.fqPtr++];        // a literal that just became false
      const list = W[this.li(fl)];
      for (let k = 0; k < list.length; k++) {
        const ci = list[k];
        // Stale watch entry (the clause moved its watch away earlier): skip.
        if (w1[ci] !== fl && w2[ci] !== fl) continue;
        const ot = (w1[ci] === fl) ? w2[ci] : w1[ci];
        if (this.litVal(ot) === 1) continue;   // clause satisfied (other watch true)
        // Look for a replacement watch: any literal != fl, ot that is non-false.
        let repl = 0;
        const c = cls[ci];
        for (let j = 0; j < c.length; j++) {
          const l = c[j];
          if (l === fl || l === ot) continue;
          if (this.litVal(l) !== -1) { repl = l; break; }
        }
        if (repl !== 0) {                      // move the watch
          if (w1[ci] === fl) w1[ci] = repl; else w2[ci] = repl;
          W[this.li(repl)].push(ci);
          continue;
        }
        // No replacement: the clause is unit at ot, or conflicting.
        const ov = this.litVal(ot);
        if (ov === 0) {
          this.assignLit(ot, this.decisionLevel, ci);   // unit propagation
        } else {
          this.fq.length = 0; this.fqPtr = 0;
          return ci;                                    // conflict (clause falsified)
        }
      }
    }
    this.fq.length = 0; this.fqPtr = 0;
    return -1;
  }

  // Undo every assignment above decision level bt (non-chronological backjump).
  // Note: watch lists need no repair — they only ever reference literals, and
  // unassignment cannot create new false literals, so no clause can become
  // newly unit/conflicted that was not already safe. Propagation resumes from
  // the asserting literal enqueued right after this call.
  cancelUntil(bt) {
    const trail = this.trail, val = this.val, lvl = this.lvl, reason = this.reason;
    while (trail.length > 0) {
      const lit = trail[trail.length - 1];
      const v = abs(lit);
      if (lvl[v] <= bt) break;
      val[v] = 0; lvl[v] = 0; reason[v] = -1;
      trail.pop();
    }
    this.decisionLevel = bt;
  }

  // First-UIP conflict analysis. Returns the learned clause with the asserting
  // (1UIP) literal at index 0, or null if an empty clause was derived (UNSAT).
  analyze(conflIdx) {
    const dl = this.decisionLevel;
    const n = this.n;
    const seen = new Array(n + 1).fill(false);
    const dropped = new Array(n + 1).fill(false);
    const learn = [];
    let dlCount = 0;
    for (const lit of this.clauses[conflIdx]) {
      const v = abs(lit);
      if (!seen[v]) { seen[v] = true; if (this.lvl[v] === dl) dlCount++; learn.push(lit); }
    }
    let i = this.trail.length - 1;
    while (dlCount > 1) {
      const p = this.trail[i--];                    // most recent assignment
      const v = abs(p);
      if (!seen[v] || this.lvl[v] !== dl) continue;
      const rc = this.reason[v];                    // antecedent clause of p
      if (rc < 0) { dlCount = 1; break; }           // defensive; should not happen
      dropped[v] = true;                            // resolve p away
      dlCount--;
      for (const lit of this.clauses[rc]) {
        const w = abs(lit);
        if (!seen[w]) { seen[w] = true; if (this.lvl[w] === dl) dlCount++; learn.push(lit); }
      }
    }
    // Final clause: drop resolved-away variables, put the unique
    // decision-level literal (the 1UIP) at the front.
    const learned = [];
    for (const lit of learn) if (!dropped[abs(lit)]) learned.push(lit);
    let uip = -1;
    for (let k = 0; k < learned.length; k++) if (this.lvl[abs(learned[k])] === dl) { uip = k; break; }
    if (uip < 0) return null;
    if (uip > 0) { const t = learned[0]; learned[0] = learned[uip]; learned[uip] = t; }
    return learned;
  }

  // Add a learned clause that is unit after the backjump and assert its
  // first literal (the 1UIP) with this clause as its antecedent.
  addClauseAssert(learned) {
    const ci = this.clauses.length;
    this.clauses.push(learned);
    this.w1.push(0); this.w2.push(0);
    if (learned.length >= 2) {
      this.w1[ci] = learned[0]; this.w2[ci] = learned[1];
      this.watches[this.li(learned[0])].push(ci);
      this.watches[this.li(learned[1])].push(ci);
    } else {                                       // learned unit clause
      this.w1[ci] = learned[0]; this.w2[ci] = learned[0];
      this.watches[this.li(learned[0])].push(ci);
    }
    this.assignLit(learned[0], this.decisionLevel, ci);
  }

  // VSIDS decision heuristic: highest-activity unassigned variable (ties broken
  // by lowest index); the value is the saved phase when available.
  pickVar() {
    let best = 0, bestAct = -1;
    for (let v = 1; v <= this.n; v++) {
      if (this.val[v] !== 0) continue;
      const a = this.act[v];
      if (a > bestAct || (a === bestAct && (best === 0 || v < best))) { best = v; bestAct = a; }
    }
    return best;
  }

  // Main search loop. Returns the final assignment array (SAT) or null (UNSAT).
  solve() {
    const n = this.n;
    const RESTART_BASE = 256;
    let restartLimit = luby(1) * RESTART_BASE;

    let confl = this.propagate();
    if (confl !== -1) return null;                 // conflict at decision level 0

    while (true) {
      confl = this.propagate();
      if (confl === -1) {
        if (this.trail.length === n) {             // all variables assigned, no conflict
          const model = new Array(n + 1);
          for (let v = 1; v <= n; v++) model[v] = this.val[v];
          return model;                            // SAT
        }
        const v = this.pickVar();
        const sign = this.phase[v] !== 0 ? this.phase[v] : 1;
        this.decisionLevel++;
        this.assignLit(sign > 0 ? v : -v, this.decisionLevel, -1);
        continue;
      }

      // --- conflict: learn a 1UIP clause, backjump, assert ---
      this.conflicts++;
      this.conflictsSinceRestart++;
      if (this.decisionLevel === 0) return null;   // UNSAT (conflict at level 0)
      const learned = this.analyze(confl);
      if (learned === null) return null;           // empty learned clause => UNSAT

      // VSIDS update with exponential recency decay + periodic rescaling.
      for (const lit of learned) this.act[abs(lit)] += this.inc;
      this.inc *= 1.0 / 0.95;
      if (this.inc > 1e20 || this.act[abs(learned[0])] > 1e20) {
        for (let v = 1; v <= n; v++) this.act[v] *= 1e-100;
        this.inc *= 1e-100;
      }

      // Backjump to the asserting decision level: the second-highest level
      // among the learned clause's literals (the 1UIP itself is at dl > bt).
      let bt = 0;
      for (let k = 1; k < learned.length; k++) {
        const l = this.lvl[abs(learned[k])];
        if (l > bt) bt = l;
      }
      this.cancelUntil(bt);
      this.addClauseAssert(learned);               // asserts the 1UIP at level bt

      // Luby-style restart policy (phase saving keeps restarts cheap/focused).
      if (this.conflictsSinceRestart >= restartLimit) {
        this.cancelUntil(0);
        this.conflictsSinceRestart = 0;
        this.restarts++;
        restartLimit = luby(this.restarts + 1) * RESTART_BASE;
      }
    }
  }
}

// ---------------------------------------------------------------------------
// DIMACS parsing, problem wrapper, model verification
// ---------------------------------------------------------------------------

function parseDimacs(text) {
  let n = 0;
  const clauses = [];
  for (const rawLine of text.split('\n')) {
    let line = rawLine.trim();
    if (line === '' || line[0] === 'c') continue;
    if (line.startsWith('p ')) {
      const parts = line.split(/\s+/);
      if (parts.length >= 3) n = parseInt(parts[2], 10);
      continue;
    }
    const parts = line.split(/\s+/);
    let curr = [];
    for (const tk of parts) {
      if (tk === '') continue;
      if (tk === 'c' || tk === '%') break;         // inline comment / end marker
      const x = parseInt(tk, 10);
      if (Number.isNaN(x)) continue;
      if (x === 0) { clauses.push(curr); curr = []; }
      else curr.push(x);
    }
    if (curr.length > 0) clauses.push(curr);       // tolerate missing terminal 0
  }
  if (n === 0) {                                   // headerless fallback
    for (const c of clauses) for (const l of c) n = Math.max(n, abs(l));
  }
  return { n, clauses };
}

// Sanitize the clause set, enforce input unit clauses at level 0, then run CDCL.
// Returns { sat, clauses (final DB, incl. learned), model }.
function solveCNF(n, rawClauses) {
  const built = [];                                // proper clauses (size >= 2)
  const units = [];
  let maxVar = n;
  for (const raw of rawClauses) {
    const c = sanitize(raw);
    if (c === null) continue;                      // tautology: drop (always satisfied)
    for (const l of c) maxVar = Math.max(maxVar, abs(l));
    if (c.length === 0) return { sat: false, clauses: built, model: null }; // empty clause
    if (c.length === 1) units.push(c[0]);
    else built.push(c);
  }
  if (maxVar === 0) maxVar = n;
  const solver = new CDCL(maxVar, built);
  // Enforce input unit clauses at decision level 0 (they are never undone).
  for (const lit of units) {
    const v = abs(lit);
    if (solver.val[v] === 0) solver.assignLit(lit, 0, -1);
    else if (solver.litVal(lit) !== 1) return { sat: false, clauses: solver.clauses, model: null };
  }
  // Install the two watched literals for every proper input clause.
  for (let ci = 0; ci < built.length; ci++) {
    const c = built[ci];
    solver.w1[ci] = c[0]; solver.w2[ci] = c[1];
    solver.watches[solver.li(c[0])].push(ci);
    solver.watches[solver.li(c[1])].push(ci);
  }
  const model = solver.solve();
  return {
    sat: model !== null,
    clauses: solver.clauses,
    model,
    conflicts: solver.conflicts,
    restarts: solver.restarts,
  };
}

// Verify that `val` (indexed 1..n, entries -1/1) satisfies every clause and is total.
function checkModel(n, clauses, val) {
  if (!val) return false;
  for (let v = 1; v <= n; v++) if (val[v] === 0) return false;
  for (const c of clauses) {
    let ok = false;
    for (const l of c) {
      const x = val[abs(l)] * (l > 0 ? 1 : -1);
      if (x === 1) { ok = true; break; }
    }
    if (!ok) return false;
  }
  return true;
}

// ---------------------------------------------------------------------------
// Test instance generators
// ---------------------------------------------------------------------------

// Pigeonhole principle: p pigeons, h holes.
//  - one clause per pigeon:  pigeon i is in (at least) one hole
//  - one clause per (pigeon pair, hole):  a hole holds at most one pigeon
function phpClauses(p, h) {
  const clauses = [];
  const x = (i, j) => (i - 1) * h + j;
  for (let i = 1; i <= p; i++) {
    const c = [];
    for (let j = 1; j <= h; j++) c.push(x(i, j));
    clauses.push(c);
  }
  for (let j = 1; j <= h; j++)
    for (let a = 1; a <= p; a++)
      for (let b = a + 1; b <= p; b++)
        clauses.push([-x(a, j), -x(b, j)]);
  return { n: p * h, clauses };
}

// Random 3-CNF built around a planted random assignment: every clause contains
// at least one literal that is true under the planted model.
function planted(n, m, seed) {
  const rng = makeRng(seed);
  const model = new Array(n + 1);
  for (let v = 1; v <= n; v++) model[v] = (rng() & 1) ? 1 : -1;
  const clauses = [];
  const seen = new Set();
  let guard = 0;
  while (clauses.length < m && guard++ < m * 100) {
    const vs = new Set();
    while (vs.size < 3) vs.add(1 + (rng() % n));
    const vars = [...vs];
    const lits = vars.map(v => {
      const sign = (rng() & 1) ? 1 : -1;
      return sign * v;
    });
    if (lits.every(l => (l > 0 ? 1 : -1) !== model[abs(l)])) {
      const fl = rng() % 3;                    // force >=1 literal true under planting
      lits[fl] = -lits[fl];
    }
    const key = lits.slice().sort((a, b) => abs(a) - abs(b)).join(',');
    if (!seen.has(key)) { seen.add(key); clauses.push(lits); }
  }
  return { n, clauses, model };
}

function toDimacs(n, clauses) {
  let s = 'p cnf ' + n + ' ' + clauses.length + '\n';
  for (const c of clauses) s += c.join(' ') + ' 0\n';
  return s;
}

// ---------------------------------------------------------------------------
// Brute force reference (used only by the self-tests, never by the solver)
// ---------------------------------------------------------------------------
function bruteSolve(n, clauses) {
  const total = 1 << n;
  outer:
  for (let mask = 0; mask < total; mask++) {
    for (const c of clauses) {
      let ok = false;
      for (const l of c) {
        const v = abs(l);
        const bit = (mask >> (v - 1)) & 1;
        if ((l > 0) === (bit === 1)) { ok = true; break; }
      }
      if (!ok) continue outer;
    }
    const model = new Array(n + 1);
    for (let v = 1; v <= n; v++) model[v] = (mask >> (v - 1)) & 1 ? 1 : -1;
    return model;
  }
  return null;
}

// ---------------------------------------------------------------------------
// Self-tests
// ---------------------------------------------------------------------------
function runSelfTest() {
  let pass = 0, fail = 0;
  const ok = (name, cond, info) => {
    if (cond) { pass++; console.log('  ok   ' + name); }
    else { fail++; console.log('  FAIL ' + name + (info ? '  -> ' + info : '')); }
  };

  console.log('== self-test: CDCL SAT solver ==');

  // ---------- (a) pigeonhole PHP(3,2): must be UNSAT ----------
  const php = phpClauses(3, 2);
  const phpDimacs = toDimacs(php.n, php.clauses);
  const parsed = parseDimacs(phpDimacs);
  const rPhp = solveCNF(parsed.n, parsed.clauses);
  ok('PHP(3,2) parser: header 6 vars / 9 clauses',
     parsed.n === 6 && parsed.clauses.length === 9,
     parsed.n + ' vars / ' + parsed.clauses.length + ' clauses');
  ok('PHP(3,2) is unsatisfiable -> solver prints UNSAT', rPhp.sat === false);
  ok('PHP(3,2) brute-force agrees (UNSAT)', bruteSolve(php.n, php.clauses) === null);
  const extra = [[4, 3], [5, 4]];
  for (const [p, h] of extra) {
    const ph = phpClauses(p, h);
    const rr = solveCNF(ph.n, ph.clauses);
    ok('PHP(' + p + ',' + h + ') UNSAT '
       + '(' + ph.n + ' vars, ' + ph.clauses.length + ' clauses, '
       + rr.conflicts + ' conflicts)', rr.sat === false && bruteSolve(ph.n, ph.clauses) === null);
  }

  // ---------- (b) planted random 3-CNF, 40 vars / 120 clauses: must be SAT ----------
  const pd = planted(40, 120, 0x5EED);
  const pDimacs = toDimacs(pd.n, pd.clauses);
  const pp = parseDimacs(pDimacs);
  const t0 = Date.now();
  const rPl = solveCNF(pp.n, pp.clauses);
  const elPl = Date.now() - t0;
  ok('planted 40x120 is satisfiable -> solver prints SAT', rPl.sat === true);
  ok('planted 40x120 model re-verified against all clauses incl. learned', checkModel(pp.n, rPl.clauses, rPl.model));
  // the printed model contains exactly one literal per variable
  const line = [];
  for (let v = 1; v <= 40; v++) line.push(rPl.model[v] > 0 ? v : -v);
  ok('planted model line has no literal + its negation', new Set(line.map(abs)).size === 40);
  console.log('      [planted solve time: ' + elPl + ' ms, ' +
              rPl.conflicts + ' conflicts, ' + rPl.restarts + ' restarts]');

  // ---------- brute-force cross-check on many random tiny formulas ----------
  console.log('  -- brute-force cross-check over random tiny formulas --');
  let bad = 0;
  for (let seed = 1; seed <= 60; seed++) {
    const rng = makeRng(seed * 7919 + 13);
    const n = 4 + (seed % 7);                      // 4..10 vars
    const m = 1 + (seed % 24);                     // 1..24 clauses
    const cls = [];
    for (let j = 0; j < m; j++) {
      const k = 1 + (rng() % 3);                   // clause width 1..3
      const vars = new Set();
      while (vars.size < k) vars.add(1 + (rng() % n));
      const c = [...vars].map(v => (rng() & 1) ? v : -v);
      cls.push(c);
    }
    const res = solveCNF(n, cls);
    const ref = bruteSolve(n, cls);
    const same = (res.sat === (ref !== null));
    if (!same) { bad++; console.log('      MISMATCH seed=' + seed + ' n=' + n); }
    if (res.sat && !checkModel(n, res.clauses, res.model)) { bad++; console.log('      BAD MODEL seed=' + seed); }
  }
  ok('60 random tiny formulas match brute force', bad === 0);

  // planted tiny formulas: guaranteed SAT, solver must find a valid model
  let bad2 = 0;
  for (let seed = 101; seed <= 125; seed++) {
    const g = planted(6 + (seed % 4), 12 + (seed % 8), seed);
    const res = solveCNF(g.n, g.clauses);
    if (!res.sat || !checkModel(g.n, res.clauses, res.model)) bad2++;
  }
  ok('25 planted tiny formulas: SAT + valid model', bad2 === 0);

  // ---------- edge cases ----------
  const E = [];
  E.push(['empty clause', 2, [[]], false]);
  E.push(['unit conflict', 2, [[1], [-1]], false]);
  E.push(['tautology only', 2, [[1, -1], [2, -2]], true]);
  E.push(['dup literals', 3, [[2, 2, -8], [3, -3]], true]);   // tautology dropped; 2∨-8 is SAT
  E.push(['n=0 empty formula', 0, [], true]);
  let badE = 0;
  for (const [name, n, cls, want] of E) {
    const res = solveCNF(n, cls);
    const got = res.sat;
    const refOK = bruteSolve(n, cls) !== null;
    if (got !== want || refOK !== want) { badE++; console.log('      edge mismatch: ' + name); }
  }
  ok('edge cases (empty/unit/tautology/n=0) all correct', badE === 0);

  // ---------- exact CLI output ----------
  console.log('  -- exact CLI outputs --');
  console.log('    php(3,2):     ' + (rPhp.sat ? 'SAT' : 'UNSAT'));
  console.log('    planted:      ' + (rPl.sat ? 'SAT' : 'UNSAT'));
  console.log('    model line:   ' + line.join(' '));

  console.log('');
  console.log('RESULT: ' + pass + ' passed, ' + fail + ' failed');
  process.exit(fail > 0 ? 1 : 0);
}

// ---------------------------------------------------------------------------
// CLI entry point
// ---------------------------------------------------------------------------
function main() {
  const argv = process.argv.slice(1);
  if (argv.includes('--selftest')) {
    runSelfTest();
    return;
  }
  const text = fs.readFileSync(0, 'utf8');
  const { n, clauses } = parseDimacs(text);
  const res = solveCNF(n, clauses);
  if (!res.sat) {
    console.log('UNSAT');
    return;
  }
  if (!checkModel(n, res.clauses, res.model)) {
    console.error('internal error: candidate model failed verification');
    process.exit(3);
  }
  console.log('SAT');
  const line = [];
  for (let v = 1; v <= n; v++) line.push(res.model[v] > 0 ? v : -v);
  console.log(line.join(' '));
}

if (require.main === module) main();
