`verify-model.js` (independent, argv-free model checker used in verification):

```javascript
// Independent model verifier (used only to double-check solver output).
// Usage: F=<cnf> M=<model> VARS=<n> node verify-model.js
'use strict';
const fs = require('fs');
const f = process.env.F, mf = process.env.M, n = parseInt(process.env.VARS, 10);
const clauses = [];
let maxv = 0;
for (const raw of fs.readFileSync(f, 'utf8').split('\n')) {
  const line = raw.trim();
  if (line === '' || line[0] === 'c') continue;
  if (line.startsWith('p ')) continue;
  const parts = line.split(/\s+/);
  let cur = [];
  for (const t of parts) {
    const x = parseInt(t, 10);
    if (x === 0) { if (cur.length) clauses.push(cur); cur = []; }
    else if (!isNaN(x)) { cur.push(x); maxv = Math.max(maxv, Math.abs(x)); }
  }
}
if (maxv !== n) { console.log('variable-count mismatch', maxv, n); process.exit(9); }
const model = {};
for (const t of fs.readFileSync(mf, 'utf8').trim().split(/\s+/)) {
  const x = parseInt(t, 10);
  if (model[Math.abs(x)]) { console.log('literal and its negation in model'); process.exit(9); }
  model[Math.abs(x)] = x > 0 ? 1 : -1;
}
if (Object.keys(model).length !== maxv) { console.log('model incomplete'); process.exit(9); }
let bad = 0;
for (const c of clauses) {
  let ok = false;
  for (const l of c) if (model[Math.abs(l)] * (l > 0 ? 1 : -1) === 1) { ok = true; break; }
  if (!ok) bad++;
}
console.log('checked ' + clauses.length + ' clauses x ' + maxv + ' vars: violations=' + bad);
process.exit(bad ? 1 : 0);
```

